		public static ushort stealthRock_CalcDamage(global::Dpr.Battle.Logic.BTL_POKEPARAM target, byte damageType) {
			// max-HP denominator by type affinity: rodata table @03d59d2c for TYPEAFF_1_64..TYPEAFF_64, 8 otherwise
			uint denom;
