			{
				case Pml.Battle.TypeAffinity.AffinityID.TYPEAFF_1_64:
				case Pml.Battle.TypeAffinity.AffinityID.TYPEAFF_1_32:
					denom = 256;
					break;
				case Pml.Battle.TypeAffinity.AffinityID.TYPEAFF_1_16:
					denom = 128;
					break;
				case Pml.Battle.TypeAffinity.AffinityID.TYPEAFF_1_8:
					denom = 64;
					break;
				case Pml.Battle.TypeAffinity.AffinityID.TYPEAFF_1_4:
					denom = 32;
					break;
				case Pml.Battle.TypeAffinity.AffinityID.TYPEAFF_1_2:
					denom = 16;
					break;
				case Pml.Battle.TypeAffinity.AffinityID.TYPEAFF_1:
					denom = 8;
					break;
				case Pml.Battle.TypeAffinity.AffinityID.TYPEAFF_2:
					denom = 4;
					break;
				case Pml.Battle.TypeAffinity.AffinityID.TYPEAFF_4:
					denom = 2;
					break;
				case Pml.Battle.TypeAffinity.AffinityID.TYPEAFF_8:
				case Pml.Battle.TypeAffinity.AffinityID.TYPEAFF_16:
				case Pml.Battle.TypeAffinity.AffinityID.TYPEAFF_32:
