			byte pokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			if ((byte)Common.PokeIDtoSide(args, pokeID) != mySide)
				return;
			// a G-move through Mat Block: RATIO_EX 0x400 = FX32 0.25
			if (!Common.RewriteEventVar(args, EventVar.Label.RATIO_EX, 1024))
				return;

			// work[0] = count of pierced targets, work[1..6] = their poke IDs (unsigned bound `cmp #5 ; b.hi` @0193ae68)
			int count = Common.GetWorkValue(args, 0);
			Common.SetWorkValue(args, 0, count + 1);
			if ((uint)count < 6)
				Common.SetWorkValue(args, (byte)(count + 1), pokeID);
		}
		public static void handler_side_Tatamigaeshi_MsgAfterCritical(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte mySide) {
			byte pokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			if ((byte)Common.PokeIDtoSide(args, pokeID) != mySide)
				return;

			int count = Common.GetWorkValue(args, 0);
			if (count == 0)
				return;

			var desc = new Section_FromEvent_Message.Description();
			desc.pokeID = pokeID;
			desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.protectpierce);
			desc.message.AddArg(pokeID);
			Common.Message(args, desc);
			Common.SetWorkValue(args, 0, count - 1);
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_SIDE_TrickGuard() {
			return HandlerTable_TrickGuard;
		}
		public static void handler_side_TrickGuard(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte mySide) {
			byte pokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			if ((byte)Common.PokeIDtoSide(args, pokeID) != mySide)
				return;

			int wazaID = Common.GetEventVar(args, EventVar.Label.WAZAID);
			int targetType = Common.GetEventVar(args, EventVar.Label.TARGET_TYPE);
			if (WAZADATA.IsDamage((Pml.WazaNo)wazaID))
				return;
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) == pokeID)
				return;
			if (targetType == (int)WazaTarget.TARGET_FRIEND_ALL || targetType == (int)WazaTarget.TARGET_ALL)
				return;
			if (!Common.RewriteEventVar(args, EventVar.Label.NOEFFECT_FLAG, 1))
				return;

			StrParam strParam = (StrParam)Common.GetEventVarAddress(args, EventVar.Label.WORK_ADRS);
			strParam.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.TrickGuard);
			strParam.AddArg(pokeID);
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_SIDE_Makibisi() {
			return HandlerTable_Makibisi;
		}
		public static void handler_side_Makibisi(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte mySide) {
			byte pokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID);
			byte side = (byte)Common.PokeIDtoSide(args, pokeID);
			if (side != mySide)
				return;

			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			var floatDesc = new Section_CheckFloating.Description();
			floatDesc.target = bpp;
			floatDesc.isIncludeHikouType = true;
			if (Common.CheckFloating(args, floatDesc))
				return;

			// Spikes layers: 2 -> 1/6, 3 -> 1/4, otherwise 1/8 max HP (two `csel eq` @0193b448 / 0193b460)
			byte addCounter = Common.GetMyAddCounter(args, (BtlSide)side);
			uint denom = (addCounter == 3) ? 4u : ((addCounter == 2) ? 6u : 8u);
			// GetSickCont inlined (its init flag 0x4cbc4b8 @0193b47c)
			GetSickCont(args, out BTL_SICKCONT sickCont);

			var desc = new Section_FromEvent_Damage.Description();
			desc.pokeID = PokeID.INVALID;
			desc.targetPokeID = pokeID;
			desc.damage = (ushort)calc.QuotMaxHP(bpp, denom, true);
			desc.damageCause = DamageCause.MAKIBISI;
			desc.damageCausePokeID = sickCont.causePokeID;
			desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.MakibisiDamage);
			desc.successMessage.AddArg(pokeID);
			Common.Damage(args, desc);
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_SIDE_Dokubisi() {
			return HandlerTable_Dokubisi;
		}
		public static void handler_side_Dokubisi(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte mySide) {
			byte pokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID);
			byte side = (byte)Common.PokeIDtoSide(args, pokeID);
			if (side != mySide)
				return;

			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			var floatDesc = new Section_CheckFloating.Description();
			floatDesc.target = bpp;
			floatDesc.isIncludeHikouType = true;
			if (Common.CheckFloating(args, floatDesc))
				return;

			if (bpp.IsMatchType((byte)Pml.PokeType.DOKU))
			{
				// a grounded Poison type absorbs the Toxic Spikes
				var removeDesc = new Section_SideEffect_Remove.Description();
				removeDesc.pokeID = pokeID;
				removeDesc.side = (BtlSide)side;
				calc.BITFLG_Construction(removeDesc.flags);
				calc.BITFLG_Set(removeDesc.flags, (uint)BtlSideEffect.BTL_SIDEEFF_DOKUBISI);
				Common.RemoveSideEffect(args, removeDesc);
			}
			else
			{
				// GetSickCont inlined (its init flag 0x4cbc4b8 @0193b844)
				GetSickCont(args, out BTL_SICKCONT sickCont);

				var sickDesc = new Section_AddSick.Description();
				sickDesc.pokeID = PokeID.INVALID;
				sickDesc.targetPokeID = pokeID;
				sickDesc.sickID = WazaSick.WAZASICK_DOKU;
				sickDesc.sickCause = SickCause.DOKUBISI;
				// one layer: regular poison; two or more: badly poisoned (`cmp #2 ; b.hs` @0193b930)
				byte addCounter = Common.GetMyAddCounter(args, (BtlSide)side);
				byte causePokeID = sickCont.causePokeID;
				if (addCounter < 2)
					sickDesc.sickCont = SICKCONT.MakePermanent(causePokeID);
				else
					sickDesc.sickCont = SICKCONT.MakeMoudokuCont(causePokeID);
				Common.AddSick(args, sickDesc);
			}
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_SIDE_NebaNebaNet() {
			return HandlerTable_NebaNebaNet;
		}
		public static void handler_side_NebaNebaNet(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte mySide) {
			byte pokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID);
			if ((byte)Common.PokeIDtoSide(args, pokeID) != mySide)
				return;

			// here the Description is allocated BEFORE GetPokeParam (@0193babc / 0193bb04)
			var floatDesc = new Section_CheckFloating.Description();
			floatDesc.target = Common.GetPokeParam(args, pokeID);
			floatDesc.isIncludeHikouType = true;
			if (Common.CheckFloating(args, floatDesc))
				return;

			// GetSickCont inlined (its init flag 0x4cbc4b8 @0193bb58)
			GetSickCont(args, out BTL_SICKCONT sickCont);

			var desc = new Section_FromEvent_RankEffect.Description();
			desc.pokeID = sickCont.causePokeID;
			desc.targetPokeCount = 1;
			desc.targetPokeID[0] = pokeID;
			desc.rankType = WazaRankEffect.AGILITY;
			desc.rankVolume = -1;
			desc.cause = RankEffectCause.NEBANEBANET;
			desc.isPreEffectMessageEnable = true;
			desc.isMigawariThrew = true;
			desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.NebaNebaNet);
			desc.message.AddArg(pokeID);
			Common.RankEffect(args, desc);
		}
