		public static void handler_Rainbow(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte mySide) {
			// Water + Fire Pledge rainbow: the attacker's side doubles the added-effect chance, kept to 16 bits
			// (`ubfiz w2, w0, #1, #0xf` @0193be4c = (v & 0x7fff) << 1)
			byte pokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			if ((byte)Common.PokeIDtoSide(args, pokeID) != mySide)
				return;

			Common.RewriteEventVar(args, EventVar.Label.ADD_PER, (ushort)(Common.GetEventVar(args, EventVar.Label.ADD_PER) * 2));
		}
		public static void handler_Rainbow_Shrink(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte mySide) {
			byte pokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			if ((byte)Common.PokeIDtoSide(args, pokeID) != mySide)
				return;

			// in WAZA_SHRINK_PER, CRITICAL_FLAG is the "double the flinch chance" flag (EventLauncher reads it as doubleFlag)
			Common.RewriteEventVar(args, EventVar.Label.CRITICAL_FLAG, 1);
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_SIDE_Burning() {
