		}
		public static void handler_side_Burning(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte mySide) {
			byte pokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID);
			if (pokeID == PokeID.INVALID)
				return;
			if (!Common.IsExistPoke(args, pokeID))
				return;
			if (Common.CheckShowDown(args))
				return;
			if ((byte)Common.PokeIDtoSide(args, pokeID) != mySide)
				return;

			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (bpp.IsMatchType((byte)Pml.PokeType.HONOO))
				return;

			var effDesc = new Section_FromEvent_AddViewEffect.Description();
			effDesc.effectNo = (ushort)BtlEff.BTLEFF_BURNING;
			effDesc.pos_from = Common.PokeIDtoPokePos(args, pokeID);
			effDesc.pos_to = BtlPokePos.POS_NULL;
			Common.AddViewEffect(args, effDesc);

			// GetSickCont inlined (its init flag 0x4cbc4b8 @0193c1a4)
			GetSickCont(args, out BTL_SICKCONT sickCont);

			var desc = new Section_FromEvent_Damage.Description();
			desc.pokeID = PokeID.INVALID;
			desc.targetPokeID = pokeID;
			desc.damage = (ushort)calc.QuotMaxHP(bpp, 8, true);
			desc.damageCause = DamageCause.BURNING;
			desc.damageCausePokeID = sickCont.causePokeID;
			desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.BurningDamage);
			desc.successMessage.AddArg(pokeID);
			Common.Damage(args, desc);
		}
